/* A read starting one byte before the partition's end, but 2 bytes long,
 * extends exactly one byte past the declared partition size and must be
 * rejected.
 */
ZTEST(flash_map, test_flash_area_bounds_offbyone)
{
	const struct flash_area *fa;
	uint8_t dst_buf[2];
	int rc;

	fa = PARTITION(SLOT1_PARTITION);

	rc = flash_area_read(fa, fa->fa_size - 1, dst_buf, 2);
	zassert_equal(rc, -EINVAL,
		      "expected -EINVAL reading one byte past fa_size, got %d", rc);
}
